-- Contrato de criação Base v1.3. O catálogo é gerado dos registros do produto.
-- Não altera políticas de leitura nem permite editar personagens de outros proprietários.
BEGIN;
ALTER TABLE public.characters ADD COLUMN IF NOT EXISTS creation_data jsonb;
ALTER TABLE public.characters ADD COLUMN IF NOT EXISTS creation_review jsonb NOT NULL DEFAULT '["Revisar escolhas da criação anterior"]'::jsonb;

CREATE TABLE IF NOT EXISTS public.character_creation_operations (
 user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
 operation_id uuid NOT NULL, request_hash text NOT NULL,
 character_id uuid NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,
 result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,operation_id)
);
ALTER TABLE public.character_creation_operations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.character_creation_operations FROM anon,authenticated;

CREATE OR REPLACE FUNCTION public.character_creation_catalog() RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT $catalog${"origins":{"academico":{"id":"academico","name":"Acadêmico","skills":["ciencias","investigacao"],"powers":["Saber é Poder"],"powerDescription":"Quando faz um teste usando Intelecto, você pode gastar 2 PE para receber +5 nesse teste."},"agente-de-saude":{"id":"agente-de-saude","name":"Agente de Saúde","skills":["intuicao","medicina"],"powers":["Técnica Medicinal"],"powerDescription":"Sempre que cura um personagem, você adiciona seu Intelecto no total de PV curados."},"amnesico":{"id":"amnesico","name":"Amnésico","skills":[],"powers":["Vislumbres do Passado"],"powerDescription":"Uma vez por sessão, você pode fazer um teste de Intelecto (DT 10) para reconhecer pessoas ou lugares familiares, que tenha encontrado antes de perder a memória. Se passar, recebe 1d4 PE temporários e, a critério do mestre, uma informação útil."},"artista":{"id":"artista","name":"Artista","skills":["artes","enganacao"],"powers":["Magnum Opus"],"powerDescription":"Você é famoso por uma de suas obras. Uma vez por missão, pode determinar que uma pessoa envolvida em uma cena de interação o reconheça. Você recebe +5 em testes de Presença e de perícias baseadas em Presença contra aquela pessoa. A critério do mestre, pode receber esse bônus em outras situações nas quais seria reconhecido."},"atleta":{"id":"atleta","name":"Atleta","skills":["acrobacia","atletismo"],"powers":["110%"],"powerDescription":"Quando faz um teste de perícia usando Força ou Agilidade (exceto Luta e Pontaria) você pode gastar 2 PE para receber +5 nesse teste."},"chef":{"id":"chef","name":"Chef","skills":["fortitude","profissao"],"powers":["Ingrediente Secreto"],"powerDescription":"Em cenas de interlúdio, você pode fazer a ação alimentar-se para cozinhar um prato especial. Você, e todos os membros do grupo que fizeram a ação alimentar-se, recebem o benefício de dois pratos (caso o mesmo benefício seja escolhido duas vezes, seus efeitos se acumulam)."},"criminoso":{"id":"criminoso","name":"Criminoso","skills":["crime","furtividade"],"powers":["O Crime Compensa"],"powerDescription":"No final de uma missão, escolha um item encontrado na missão. Em sua próxima missão, você pode incluir esse item em seu inventário sem que ele conte em seu limite de itens por patente."},"cultista-arrependido":{"id":"cultista-arrependido","name":"Cultista Arrependido","skills":["ocultismo","religiao"],"powers":["Traços do Outro Lado"],"powerDescription":"Você possui um poder paranormal à sua escolha. Porém, começa o jogo com metade da Sanidade normal para sua classe."},"desgarrado":{"id":"desgarrado","name":"Desgarrado","skills":["fortitude","sobrevivencia"],"powers":["Calejado"],"powerDescription":"Você recebe +1 PV para cada 5% de NEX."},"engenheiro":{"id":"engenheiro","name":"Engenheiro","skills":["profissao","tecnologia"],"powers":["Ferramenta Favorita"],"powerDescription":"Um item a sua escolha (exceto armas) conta como uma categoria abaixo (por exemplo, um item de categoria II conta como categoria I para você)."},"executivo":{"id":"executivo","name":"Executivo","skills":["diplomacia","profissao"],"powers":["Processo Otimizado"],"powerDescription":"Sempre que faz um teste de perícia durante um teste estendido, ou uma ação para revisar documentos (físicos ou digitais), pode pagar 2 PE para receber +5 nesse teste."},"investigador":{"id":"investigador","name":"Investigador","skills":["investigacao","percepcao"],"powers":["Faro para Pistas"],"powerDescription":"Uma vez por cena, quando fizer um teste para procurar pistas, você pode gastar 1 PE para receber +5 nesse teste."},"lutador":{"id":"lutador","name":"Lutador","skills":["luta","reflexos"],"powers":["Mão Pesada"],"powerDescription":"Você recebe +2 em rolagens de dano com ataques corpo a corpo."},"magnata":{"id":"magnata","name":"Magnata","skills":["diplomacia","pilotagem"],"powers":["Patrocinador da Ordem"],"powerDescription":"Seu limite de crédito é sempre considerado um acima do atual."},"mercenario":{"id":"mercenario","name":"Mercenário","skills":["iniciativa","intimidacao"],"powers":["Posição de Combate"],"powerDescription":"No primeiro turno de cada cena de ação, você pode gastar 2 PE para receber uma ação de movimento adicional."},"militar":{"id":"militar","name":"Militar","skills":["pontaria","tatica"],"powers":["Para Bellum"],"powerDescription":"Você recebe +2 em rolagens de dano com armas de fogo."},"operario":{"id":"operario","name":"Operário","skills":["fortitude","profissao"],"powers":["Ferramenta de Trabalho"],"powerDescription":"Escolha uma arma simples ou tática que, a critério do mestre, poderia ser usada como ferramenta em sua profissão (como uma marreta para um pedreiro). Você sabe usar a arma escolhida e recebe +1 em testes de ataque, rolagens de dano e margem de ameaça com ela."},"policial":{"id":"policial","name":"Policial","skills":["percepcao","pontaria"],"powers":["Patrulha"],"powerDescription":"Você recebe +2 em Defesa."},"religioso":{"id":"religioso","name":"Religioso","skills":["religiao","vontade"],"powers":["Acalentar"],"powerDescription":"Você recebe +5 em testes de Religião para acalmar. Além disso, quando acalma uma pessoa, ela recebe um número de pontos de Sanidade igual a 1d6 + a sua Presença."},"servidor-publico":{"id":"servidor-publico","name":"Servidor Público","skills":["intuicao","vontade"],"powers":["Espírito Cívico"],"powerDescription":"Sempre que faz um teste para ajudar, você pode gastar 1 PE para aumentar o bônus concedido em +2."},"ti":{"id":"ti","name":"T.I.","skills":["investigacao","tecnologia"],"powers":["Motor de Busca"],"powerDescription":"A critério do mestre, sempre que tiver acesso à internet, você pode gastar 2 PE para substituir um teste de perícia qualquer por um teste de Tecnologia."},"teorico-da-conspiracao":{"id":"teorico-da-conspiracao","name":"Teórico da Conspiração","skills":["investigacao","ocultismo"],"powers":["Eu Já Sabia"],"powerDescription":"Você não se abala tanto com entidades ou anomalias. Afinal, sempre soube que isso tudo existia. Você recebe resistência a dano mental igual ao seu Intelecto."},"trabalhador-rural":{"id":"trabalhador-rural","name":"Trabalhador Rural","skills":["adestramento","sobrevivencia"],"powers":["Desbravador"],"powerDescription":"Quando faz um teste de Adestramento ou Sobrevivência, você pode gastar 2 PE para receber +5 nesse teste. Além disso, você não sofre penalidade em deslocamento por terreno difícil."},"trambiqueiro":{"id":"trambiqueiro","name":"Trambiqueiro","skills":["crime","enganacao"],"powers":["Impostor"],"powerDescription":"Uma vez por cena, você pode gastar 2 PE para substituir um teste de perícia qualquer por um teste de Enganação."},"universitario":{"id":"universitario","name":"Universitário","skills":["atualidades","investigacao"],"powers":["Dedicação"],"powerDescription":"Você recebe +1 PE, e mais 1 PE adicional a cada NEX ímpar (15%, 25%...). Além disso, seu limite de PE por turno aumenta em 1 (em NEX 5% seu limite é 2, em NEX 10% é 3 e assim por diante; isso não afeta a DT de seus efeitos)."},"vitima":{"id":"vitima","name":"Vítima","skills":["reflexos","vontade"],"powers":["Cicatrizes Psicológicas"],"powerDescription":"Você recebe +1 de Sanidade para cada 5% de NEX."}},"classes":{"Combatente":{"hp":20,"hpGain":4,"pe":2,"peGain":2,"san":12,"sanGain":3,"mandatory":[],"choices":[{"id":"combat","options":["luta","pontaria"],"pick":1,"label":"Luta ou Pontaria"},{"id":"defense","options":["fortitude","reflexos"],"pick":1,"label":"Fortitude ou Reflexos"}],"free":1,"proficiencies":["Armas simples","Armas táticas","Proteções leves"],"core":{"5":["Ataque Especial"],"10":["Ataque Especial","Habilidade de Trilha"],"15":["Ataque Especial","Habilidade de Trilha"],"20":["Ataque Especial","Habilidade de Trilha","Aumento de Atributo"],"25":["Ataque Especial","Habilidade de Trilha","Aumento de Atributo"],"30":["Ataque Especial","Habilidade de Trilha","Aumento de Atributo"],"35":["Ataque Especial","Habilidade de Trilh