Treinamento","Aumento de Atributo","Versatilidade","3º Círculo de Rituais"],"60":["Escolhido pelo Outro Lado","Habilidade de Trilha","Aumento de Atributo","2º Círculo de Rituais","Grau de Treinamento","Aumento de Atributo","Versatilidade","3º Círculo de Rituais"],"65":["Escolhido pelo Outro Lado","Habilidade de Trilha","Aumento de Atributo","2º Círculo de Rituais","Grau de Treinamento","Aumento de Atributo","Versatilidade","3º Círculo de Rituais"],"70":["Escolhido pelo Outro Lado","Habilidade de Trilha","Aumento de Atributo","2º Círculo de Rituais","Grau de Treinamento","Aumento de Atributo","Versatilidade","3º Círculo de Rituais","Grau de Treinamento"],"75":["Escolhido pelo Outro Lado","Habilidade de Trilha","Aumento de Atributo","2º Círculo de Rituais","Grau de Treinamento","Aumento de Atributo","Versatilidade","3º Círculo de Rituais","Grau de Treinamento"],"80":["Escolhido pelo Outro Lado","Habilidade de Trilha","Aumento de Atributo","2º Círculo de Rituais","Grau de Treinamento","Aumento de Atributo","Versatilidade","3º Círculo de Rituais","Grau de Treinamento","Aumento de Atributo"],"85":["Escolhido pelo Outro Lado","Habilidade de Trilha","Aumento de Atributo","2º Círculo de Rituais","Grau de Treinamento","Aumento de Atributo","Versatilidade","3º Círculo de Rituais","Grau de Treinamento","Aumento de Atributo","4º Círculo de Rituais"],"90":["Escolhido pelo Outro Lado","Habilidade de Trilha","Aumento de Atributo","2º Círculo de Rituais","Grau de Treinamento","Aumento de Atributo","Versatilidade","3º Círculo de Rituais","Grau de Treinamento","Aumento de Atributo","4º Círculo de Rituais"],"95":["Escolhido pelo Outro Lado","Habilidade de Trilha","Aumento de Atributo","2º Círculo de Rituais","Grau de Treinamento","Aumento de Atributo","Versatilidade","3º Círculo de Rituais","Grau de Treinamento","Aumento de Atributo","4º Círculo de Rituais","Aumento de Atributo"],"99":["Escolhido pelo Outro Lado","Habilidade de Trilha","Aumento de Atributo","2º Círculo de Rituais","Grau de Treinamento","Aumento de Atributo","Versatilidade","3º Círculo de Rituais","Grau de Treinamento","Aumento de Atributo","4º Círculo de Rituais","Aumento de Atributo"]}}},"patentLimits":{"Recruta":{"I":2,"II":0,"III":0,"IV":0},"Operador":{"I":3,"II":1,"III":0,"IV":0},"Agente Especial":{"I":3,"II":2,"III":1,"IV":0},"Oficial de Operações":{"I":3,"II":3,"III":2,"IV":1},"Agente de Elite":{"I":3,"II":3,"III":3,"IV":2}},"skills":["acrobacia","adestramento","artes","atletismo","atualidades","ciencias","crime","diplomacia","enganacao","fortitude","furtividade","iniciativa","intimidacao","intuicao","investigacao","luta","medicina","ocultismo","percepcao","pilotagem","pontaria","profissao","reflexos","religiao","sobrevivencia","tatica","tecnologia","vontade"],"patents":["Recruta","Recruta","Recruta","Operador","Operador","Operador","Operador","Operador","Operador","Agente Especial","Agente Especial","Agente Especial","Agente Especial","Agente Especial","Oficial de Operações","Oficial de Operações","Oficial de Operações","Oficial de Operações","Oficial de Operações","Agente de Elite"],"tracks":{"aniquilador":{"id":"aniquilador","name":"Aniquilador","classId":"Combatente","description":"Você é treinado para abater alvos com eficiência e velocidade. Suas armas são suas melhores amigas e você cuida tão bem delas quanto de seus companheiros de equipe. Talvez até melhor.","abilities":[{"id":"a-favorita","name":"A Favorita","description":"Escolha uma arma para ser sua favorita, como katana ou fuzil de assalto. A categoria da arma escolhida é reduzida em I.","minNex":10,"isInitial":true},{"id":"tecnica-secreta","name":"Técnica Secreta","description":"A categoria da arma favorita passa a ser reduzida em II. Quando faz um ataque com ela, você pode gastar 2 PE para executar um dos efeitos abaixo como parte do ataque. Você pode adicionar mais efeitos gastando +2 PE por efeito adicional.\n\n• Amplo. O ataque pode atingir um alvo adicional em seu alcance e adjacente ao original (use o mesmo teste de ataque para ambos).\n• Destruidor. Aumenta o multiplicador de crítico da arma em +1.","minNex":40},{"id":"tecnica-sublime","name":"Técnica Sublime","description":"Você adiciona os seguintes efeitos à lista de sua Técnica Secreta:\n\n• Letal. Aumenta a margem de ameaça em +2. Você pode escolher este efeito duas vezes para aumentar a margem de ameaça em +5.\n• Perfurante. Ignora até 5 pontos de resistência a dano de qualquer tipo do alvo.","minNex":65},{"id":"maquina-de-matar","name":"Máquina de Matar","description":"A categoria da arma favorita passa a ser reduzida em III, ela recebe +2 na margem de ameaça e seu dano aumenta em um dado do mesmo tipo.","minNex":99}]},"comandante-campo":{"id":"comandante-campo","name":"Comandante de Campo","classId":"Combatente","description":"Sem um oficial uma batalha não passa de uma briga de bar. Você é treinado para coordenar e auxiliar seus companheiros em combate, tomando decisões rápidas e tirando melhor proveito da situação e do talento de seus aliados.","abilities":[{"id":"inspirar-confianca","name":"Inspirar Confiança","description":"Sua liderança inspira seus aliados. Você pode gastar uma reação e 2 PE para fazer um aliado em alcance curto rolar novamente um teste recém realizado.","minNex":10,"isInitial":true},{"id":"estrategista","name":"Estrategista","description":"Você pode direcionar aliados em alcance curto. Gaste uma ação padrão e 1 PE por aliado que quiser direcionar (limitado pelo seu Intelecto). No próximo turno dos aliados afetados, eles ganham uma ação de movimento adicional.","minNex":40},{"id":"brecha-na-guarda","name":"Brecha na Guarda","description":"Uma vez por rodada, quando um aliado causar dano em um inimigo que esteja em seu alcance curto, você pode gastar uma reação e 2 PE para que você ou outro aliado em alcance curto faça um ataque adicional contra o mesmo inimigo. Além disso, o alcance de Inspirar Confiança e Estrategista aumenta para médio.","minNex":65},{"id":"oficial-comandante","name":"Oficial Comandante","description":"Você pode gastar uma ação padrão e 5 PE para que cada aliado que você possa ver em alcance médio receba uma ação padrão adicional no próximo turno dele.","minNex":99}]},"guerreiro":{"id":"guerreiro","name":"Guerreiro","classId":"Combatente","description":"Você treinou sua musculatura e movimentos a ponto de transformar seu corpo em uma verdadeira arma. Com golpes corpo a corpo tão poderosos quanto uma bala, você enfrenta inimigos sem medo.","abilities":[{"id":"tecnica-letal","name":"Técnica Letal","description":"Você recebe um aumento de +2 na margem de ameaça com todos os seus ataques corpo a corpo.","minNex":10,"isInitial":true},{"id":"revidar","name":"Revidar","description":"Sempre que bloquear um ataque, você pode gastar uma reação e 2 PE para fazer um ataque corpo a corpo no inimigo que o atacou.","minNex":40},{"id":"forca-opressora","name":"Força Opressora","description":"Quando acerta um ataque corpo a corpo, você pode gastar 1 PE para realizar uma manobra derrubar ou empurrar contra o alvo do ataque como ação livre. Se escolher empurrar, recebe um bônus de +5 para cada 10 pontos de dano que causou no alvo. Se escolher derrubar e vencer no teste oposto, você pode gastar 1 PE para fazer um ataque adicional contra o alvo caído.","minNex":65},{"id":"potencia-maxima","name":"Potência Máxima","description":"Quando usa seu Ataque Especial com armas corpo a corpo, todos os bônus numéricos são dobrados. Por exemplo, se usar 5 PE para receber +5 no ataque e +15 no dano, você recebe +10 no ataque e +30 no dano.","minNex":99}]},"operacoes-especiais":{"id":"operacoes-especiais","name":"Operações Especiais","classId":"Combatente","description":"Você é um combatente eficaz. Suas ações são calculadas e otimizadas, sempre antevendo os movimentos inimigos e se posicionando da maneira mais inteligente no campo de batalha.","abilities":[{"id":"iniciativa-aprimorada","name":"Iniciativa Aprimorada","description":"Você recebe +5 em Iniciativa e uma ação de movimento adicional na primeira rodada.","minNex":10,"isInitial":true},{"id":"ataque-extra","name":"Ataque Extra","description":"Uma vez por rodada, quando faz um ataque, você pode gastar 2 PE para fazer um ataque adicional.","minNex":40},{"id":"surto-de-adrenalina","name":"Surto de Adrenalina","description":"Uma vez por rodada, você pode gastar 5 PE para realizar uma ação padrão ou de movimento adicional.","minNex":65},{"id":"sempre-alerta","name":"Sempre Alerta","description":"Você recebe uma ação padrão adicional no início de cada cena de combate.","minNex":99}]},"tropa-choque":{"id":"tropa-choque","name":"Tropa de Choque","classId":"Combatente","description":"Você é duro na queda. Treinou seu corpo para resistir a traumas físicos, tornando-o praticamente inquebrável, e por isso não teme se colocar entre seus aliados e o perigo.","abilities":[{"id":"casca-grossa","name":"Casca Grossa","description":"Você recebe +1 PV para cada 5% de NEX e, quando faz um bloqueio, soma seu Vigor na resistência a dano recebida.","minNex":10,"isInitial":true},{"id":"cai-dentro","name":"Cai Dentro","description":"Sempre que um oponente em alcance curto ataca um de seus aliados, você pode gastar uma reação e 1 PE para fazer com que esse oponente faça um teste de Vontade (DT Vig). Se falhar, o oponente deve atacar você em vez de seu aliado. Este poder só funciona se você puder ser efetivamente atacado e estiver no alcance do ataque (por exemplo, adjacente a um oponente atacando em corpo a corpo ou dentro do alcance de uma arma de ataque à distância). Um oponente que passe no teste de Vontade não pode ser afetado por seu poder Cai Dentro até o final da cena.","minNex":40},{"id":"duro-de-matar","name":"Duro de Matar","description":"Ao sofrer dano não paranormal, você pode gastar uma reação e 2 PE para reduzir esse dano à metade. Em NEX 85%, você pode usar esta habilidade para reduzir dano paranormal.","minNex":65},{"id":"inquebravel","name":"Inquebrável","description":"Enquanto estiver machucado, você recebe +5 na Defesa e resistência a dano 5. Enquanto estiver morrendo, em vez do normal, você não fica indefeso e ainda pode realizar ações. Você ainda segue as regras de morte normalmente.","minNex":99}]},"atirador-elite":{"id":"atirador-elite","name":"Atirador de Elite","classId":"Especialista","description":"Um tiro, uma morte. Ao contrário dos combatentes, você é perito em neutralizar ameaças à distância, terminando uma briga antes mesmo que ela comece. Você trata sua arma como uma ferramenta de precisão, sendo capaz de executar façanhas incríveis.","abilities":[{"id":"mira-elite","name":"Mira de Elite","description":"Você recebe proficiência com armas de fogo que usam balas longas e soma seu Intelecto nas rolagens de dano com essas armas.","minNex":10,"isInitial":true},{"id":"disparo-letal","name":"Disparo Letal","description":"Quando faz a ação mirar, você pode gastar 1 PE para aumentar em +2 a margem de ameaça do próximo ataque que fizer até o final do seu próximo turno.","minNex":40},{"id":"disparo-impactante","name":"Disparo Impactante","description":"Quando ataca com uma arma de fogo, você pode gastar 2 PE e, em vez de causar dano, fazer uma manobra entre: derrubar, desarmar, empurrar ou quebrar.","minNex":65},{"id":"atirar-matar","name":"Atirar para Matar","description":"Quando faz um acerto crítico com uma arma de fogo, você causa dano máximo, sem precisar rolar os dados.","minNex":99}]},"infiltrador":{"id":"infiltrador","name":"Infiltrador","classId":"Especialista","description":"Você é um perito em infiltração e sabe neutralizar alvos desprevenidos sem causar alarde. Combinando talento acrobático, destreza manual e conhecimento técnico, você é capaz de superar qualquer barreira de defesa.","abilities":[{"id":"ataque-furtivo-trilha","name":"Ataque Furtivo","description":"Você sabe atingir os pontos vitais de um inimigo distraído. Uma vez por rodada, quando atinge um alvo desprevenido, flanqueado ou que você esteja atacando corpo a corpo com uma arma leve, pode gastar 1 PE para causar +1d6 de dano do mesmo tipo da arma. O dano adicional aumenta para +2d6 em NEX 40%, +3d6 em NEX 65% e +4d6 em NEX 99%.","minNex":10,"isInitial":true},{"id":"gatuno","name":"Gatuno","description":"Você recebe +5 em Atletismo e Crime e pode percorrer seu deslocamento normal ao se esconder, sem penalidade (veja Furtividade).","minNex":40},{"id":"assassinar","name":"Assassinar","description":"Você pode gastar uma ação de movimento e 3 PE para analisar um alvo em alcance curto. Até o final do seu próximo turno, seu próximo Ataque Furtivo causa dano dobrado e você soma seus dados de dano extras dessa habilidade duas vezes. Além disso, se o alvo ficar inconsciente ou morrendo, você escolhe se ele fica inconsciente ou morrendo (Fortitude DT Agi evita).","minNex":65},{"id":"sombra-fugaz","name":"Sombra Fugaz","description":"Quando faz um teste de Furtividade após atacar ou realizar outra ação chamativa, você pode gastar 3 PE para não sofrer penalidade no teste.","minNex":99}]},"medico-campo":{"id":"medico-campo","name":"Médico de Campo","classId":"Especialista","description":"Você é treinado em técnicas de primeiros socorros e tratamento de emergência, o que torna você um membro valioso para qualquer grupo de agentes. Ao contrário dos profissionais de saúde convencionais, você está acostumado com o campo de batalha e sabe tomar decisões rápidas no meio do caos.","abilities":[{"id":"paramedico","name":"Paramédico","description":"Você pode usar 1 ação padrão e 2 PE para curar 2d10 pontos de vida de si mesmo ou de um aliado adjacente. Você pode curar +1d10 PV respectivamente em NEX 40%, 65% e 99%, gastando +1 PE por dado adicional de cura.","minNex":10,"isInitial":true},{"id":"equipe-trauma","name":"Equipe de Trauma","description":"Você pode usar 1 ação padrão e 2 PE para remover uma condição negativa (exceto morrendo) de um aliado adjacente.","minNex":40},{"id":"resgate","name":"Resgate","description":"Uma vez por rodada, se estiver em alcance curto de um aliado machucado ou morrendo, você pode se aproximar do aliado com 1 ação livre (desde que seja capaz de fazê-lo usando seu deslocamento normal). Além disso, sempre que curar PV ou remover condições do aliado, você e o aliado recebem +5 na Defesa até o início do seu próximo turno. Por fim, para você, o total de espaços ocupados por carregar um personagem é reduzido pela metade.","minNex":65},{"id":"reanimacao","name":"Reanimação","description":"Uma vez por cena, você pode gastar 1 ação completa e 10 PE para trazer de volta à vida um personagem que tenha morrido na mesma cena (exceto morte por dano massivo).","minNex":99}]},"negociador":{"id":"negociador","name":"Negociador","classId":"Especialista","description":"Você é um diplomata habilidoso e consegue influenciar outras pessoas, seja por lábia ou intimidação. Sua capacidade de avaliar situações com rapidez e eficiência pode tirar o grupo de apuros que nem a mais poderosa das armas poderia resolver.","abilities":[{"id":"eloquencia","name":"Eloquência","description":"Você pode usar 1 ação completa e 1 PE por alvo em alcance curto para afetar outras pessoas com sua fala. Faça um teste de Diplomacia, Enganação ou Intimidação contra a Vontade dos alvos. Se você vencer, os alvos ficam fascinados enquanto você se concentrar (1 ação padrão por rodada). Um alvo hostil ou que esteja envolvido em combate recebe +5 em seu teste de resistência e tem direito a um novo teste por rodada, sempre que você se concentrar. Uma pessoa que passar no teste fica imune a este efeito por 1 dia.","minNex":10,"isInitial":true},{"id":"discurso-motivador","name":"Discurso Motivador","description":"Você pode gastar 1 ação padrão e 4 PE para inspirar seus aliados com suas palavras. Você e todos os seus aliados em alcance curto ganham +1d20 em testes de perícia até o fim da cena. A partir de NEX 65%, você pode gastar 8 PE para fornecer um bônus total de +2d20.","minNex":40},{"id":"eu-conheco-um-cara","name":"Eu Conheço um Cara","description":"Uma vez por missão, você pode ativar sua rede de contatos para pedir um favor, como por exemplo: trocar todo o equipamento do seu grupo (como se tivesse uma segunda fase de preparação de missão); ou conseguir um local de descanso; ou mesmo ser resgatado de uma cena. O mestre tem a palavra final de quando é possível usar esta habilidade e quais favores podem ser obtidos.","minNex":65},{"id":"truque-mestre","name":"Truque de Mestre","description":"Acostumado a uma vida de fingimento e manipulação, você pode gastar 5 PE para simular o efeito de qualquer habilidade que você tenha visto um de seus aliados usar durante a cena. Você ignora os pré-requisitos da habilidade, mas ainda precisa pagar todos os seus custos (incluindo ações, PE e materiais) e usar os seus parâmetros de jogo, como se você estivesse usando a habilidade em questão.","minNex":99}]},"tecnico":{"id":"tecnico","name":"Técnico","classId":"Especialista","description":"Sua principal habilidade é a manutenção e reparo do valioso equipamento que seu time carrega em missão. Seu conhecimento técnico também permite que você improvise ferramentas com o que tiver à disposição e sabote os itens usados por seus inimigos.","abilities":[{"id":"inventario-otimizado","name":"Inventário Otimizado","description":"Você soma seu Intelecto à sua Força para calcular sua capacidade de carga.","minNex":10,"isInitial":true},{"id":"remendao","name":"Remendão","description":"Você pode gastar 1 ação completa e 1 PE para remover a condição quebrado de um equipamento adjacente até o final da cena. Além disso, qualquer equipamento geral tem sua categoria reduzida em I para você.","minNex":40},{"id":"improvisar","name":"Improvisar","description":"Você pode improvisar equipamentos com materiais ao seu redor. Escolha um equipamento geral e gaste 1 ação completa e 2 PE, mais 2 PE por categoria do item escolhido. Você cria uma versão funcional do equipamento, que segue as regras de espaço e categoria como normal. Ao final da cena, seu equipamento improvisado se torna inútil.","minNex":65},{"id":"preparado-para-tudo","name":"Preparado para Tudo","description":"Você sempre tem o que precisa para qualquer situação. Sempre que precisar de um item qualquer (exceto armas), você pode gastar 1 ação de movimento e 2 PE por categoria do item para \"lembrar\" que colocou ele no fundo da bolsa. Depois de encontrado, o item segue normalmente as regras de inventário.","minNex":99}]},"condutor":{"id":"condutor","name":"Condutor","classId":"Ocultista","description":"Você domina os aspectos fundamentais da conjuração de rituais e é capaz de aumentar o alcance e a velocidade de suas conjurações. Conforme sua conexão com as entidades paranormais aumenta, você se torna capaz de interferir com os rituais de outros ocultistas.","abilities":[{"id":"ampliar-ritual","name":"Ampliar Ritual","description":"Quando lança um ritual, você pode gastar 2 PE para aumentar seu alcance em um passo (de curto para médio, de médio para longo ou de longo para extremo), ou dobrar a área de efeito.","minNex":10,"isInitial":true},{"id":"acelerar-ritual","name":"Acelerar Ritual","description":"Uma vez por rodada, você pode aumentar o custo de um ritual em 4 PE para conjurá-lo como ação livre.","minNex":40},{"id":"anular-ritual","name":"Anular Ritual","description":"Quando for alvo de um ritual, você pode gastar uma quantidade de PE igual ao custo pago por esse ritual e fazer um teste oposto de Ocultismo contra o conjurador. Se vencer, você anula o ritual, cancelando todos os seus efeitos.","minNex":65},{"id":"canalizar-o-medo","name":"Canalizar o Medo","description":"Você aprende o ritual Canalizar o Medo.","minNex":99}]},"flagelador":{"id":"flagelador","name":"Flagelador","classId":"Ocultista","description":"Dor é um poderoso catalisador paranormal. Você aprendeu a transformá-la em poder para seus rituais, usando sofrimento como instrumento de destruição.","abilities":[{"id":"poder-do-flagelo","name":"Poder do Flagelo","description":"Ao conjurar um ritual, você pode gastar seus próprios pontos de vida no lugar de PE (1 PV = 1 PE). Pontos de vida gastos dessa forma só podem ser recuperados com descanso.","minNex":10,"isInitial":true},{"id":"abracar-a-dor","name":"Abraçar a Dor","description":"Sempre que sofrer dano paranormal, você pode gastar uma reação e 2 PE para reduzir esse dano à metade.","minNex":40},{"id":"absorver-angustia","name":"Absorver Angústia","description":"Sempre que reduzir um ou mais inimigos a 0 PV com um ritual, você recebe PE temporários iguais ao círculo do ritual utilizado. Exemplo: ao usar um ritual de 2º círculo, você recebe 2 PE temporários.","minNex":65},{"id":"medo-tangivel","name":"Medo Tangível","description":"Você aprende o ritual Medo Tangível.","minNex":99}]},"graduado":{"id":"graduado","name":"Graduado","classId":"Ocultista","description":"Você foca seus estudos e se torna um conjurador versátil e poderoso, conhecendo mais rituais que outros ocultistas e sendo capaz de torná-los mais difíceis de resistir.","abilities":[{"id":"saber-ampliado","name":"Saber Ampliado","description":"Você aprende um ritual de 1º círculo. Sempre que ganhar acesso a um novo círculo, aprende um ritual adicional daquele círculo. Esses rituais não contam no limite de rituais conhecidos.","minNex":10,"isInitial":true},{"id":"grimorio-ritualistico","name":"Grimório Ritualístico","description":"Você cria um grimório especial, capaz de armazenar rituais que sua mente não conseguiria guardar. Você pode armazenar um número de rituais de 1º ou 2º círculo igual ao seu Intelecto. Sempre que ganhar acesso a um novo círculo, pode incluir um novo ritual no grimório. Rituais do grimório não contam no limite de rituais conhecidos. Para conjurar um ritual do grimório, é necessário empunhar o grimório e gastar uma ação completa para consultar o ritual. O grimório ocupa 1 espaço no inventário. Se for perdido, você pode recriá-lo com duas ações de interlúdio.","minNex":40},{"id":"rituais-eficientes","name":"Rituais Eficientes","description":"A DT para resistir aos seus rituais aumenta em +5.","minNex":65},{"id":"conhecendo-o-medo","name":"Conhecendo o Medo","description":"Você aprende o ritual Conhecendo o Medo.","minNex":99}]},"intuitivo":{"id":"intuitivo","name":"Intuitivo","classId":"Ocultista","description":"Você expande sua mente para resistir e manipular os efeitos do Outro Lado, focando em força de vontade e resistência paranormal.","abilities":[{"id":"mente-sa","name":"Mente Sã","description":"Você compreende melhor as entidades do Outro Lado. Você recebe resistência paranormal +5 (+5 em testes de resistência contra efeitos paranormais).","minNex":10,"isInitial":true},{"id":"presenca-poderosa","name":"Presença Poderosa","description":"Sua resistência mental faz com que você possa extrair mais do Outro Lado. Você soma seu limite de PE por turno à sua Presença ao conjurar rituais (não afeta a DT).","minNex":40},{"id":"inabalavel","name":"Inabalável","description":"Você recebe resistência a dano mental igual a 10. Além disso, quando é alvo de um efeito paranormal, pode fazer um teste de Vontade para reduzir o dano à metade (não sofre dano algum se passar).","minNex":65},{"id":"presenca-do-medo","name":"Presença do Medo","description":"Você aprende o ritual Presença do Medo.","minNex":99}]},"lamina-paranormal":{"id":"lamina-paranormal","name":"Lâmina Paranormal","classId":"Ocultista","description":"Alguns ocultistas preferem unir conhecimento arcano e combate físico, usando o paranormal como extensão de sua lâmina.","abilities":[{"id":"lamina-maldita","name":"Lâmina Maldita","description":"Você aprende o ritual Amaldiçoar Arma. Ao conjurá-lo, pode gastar +1 PE para reduzir o tempo de conjuração para movimento. Além disso, ao conjurar esse ritual, você pode usar Ocultismo no lugar de Luta ou Pontaria para testes de ataque com a arma amaldiçoada.","minNex":10,"isInitial":true},{"id":"gladiador-paranormal","name":"Gladiador Paranormal","description":"Sempre que acerta um ataque corpo a corpo, você recebe 2 PE temporários. Você pode ganhar um número máximo de PE temporários por cena igual ao seu limite de PE por turno. PE temporários desaparecem ao final da cena.","minNex":40},{"id":"conjuracao-marcial","name":"Conjuração Marcial","description":"Uma vez por rodada, quando lança um ritual com execução de ação padrão, você pode gastar 2 PE para fazer um ataque corpo a corpo como ação livre.","minNex":65},{"id":"lamina-do-medo","name":"Lâmina do Medo","description":"Você aprende o ritual Lâmina do Medo.","minNex":99}]}},"powers":{"armamento-pesado":{"id":"armamento-pesado","name":"Armamento Pesado","classId":"Combatente","minNex":15,"repeatable":false,"prerequisites":{"attributes":{"strength":2}},"proficiencies":{"weapons":["heavy"]}},"artista-marcial":{"id":"artista-marcial","name":"Artista Marcial","classId":"Combatente","minNex":15,"repeatable":false,"prerequisites":{}},"ataque-de-oportunidade":{"id":"ataque-de-oportunidade","name":"Ataque de Oportunidade","classId":"Combatente","minNex":15,"repeatable":false,"prerequisites":{}},"combater-duas-armas":{"id":"combater-duas-armas","name":"Combater com Duas Armas","classId":"Combatente","minNex":15,"repeatable":false,"prerequisites":{"attributes":{"agility":3},"skills":[{"skill":"luta"},{"skill":"pontaria"}]}},"combate-defensivo":{"id":"combate-defensivo","name":"Combate Defensivo","classId":"Combatente","minNex":15,"repeatable":false,"prerequisites":{"attributes":{"intellect":2}}},"golpe-demolidor":{"id":"golpe-demolidor","name":"Golpe Demolidor","classId":"Combatente","minNex":15,"repeatable":false,"prerequisites":{"attributes":{"strength":2},"skills":[{"skill":"luta","level":"trained"}]}},"golpe-pesado":{"id":"golpe-pesado","name":"Golpe Pesado","classId":"Combatente","minNex":15,"repeatable":false,"prerequisites":{}},"incansavel":{"id":"incansavel","name":"Incansável","classId":"Combatente","minNex":15,"repeatable":false,"prerequisites":{}},"pre